<script setup lang="ts">
import{onMounted,ref,watch}from'vue';import{Plus,Search}from'lucide-vue-next';import{vendorAdminAPI,getApiErrorMessage}from'../../services/api';import type{Vendor}from'../../services/api';import StatusBadge from'../../components/StatusBadge.vue';
const items=ref<Vendor[]>([]),loading=ref(true),error=ref(''),q=ref(''),status=ref(''),page=ref(1),totalPages=ref(1),createOpen=ref(false),creating=ref(false),form=ref({business_name:'',contact_name:'',email:'',phone:''}),fields=ref<Record<string,string>>({});
async function load(){loading.value=true;error.value='';try{const r=await vendorAdminAPI.getVendors({q:q.value,status:status.value,page:page.value,per_page:20});items.value=r.items;totalPages.value=r.totalPages}catch(e:unknown){error.value=getApiErrorMessage(e,'Vendors could not be loaded.')}finally{loading.value=false}}watch([q,status],()=>{page.value=1;void load()});async function create(){creating.value=true;fields.value={};error.value='';try{await vendorAdminAPI.createVendor({...form.value});createOpen.value=false;form.value={business_name:'',contact_name:'',email:'',phone:''};await load()}catch(e:any){error.value=e.response?.data?.error||'Vendor could not be created.';fields.value=e.response?.data?.fields||{}}finally{creating.value=false}}function date(v?:string){if(!v)return'-';return new Date(v).toLocaleDateString('en-KE',{day:'numeric',month:'short',year:'numeric'})}onMounted(load)
</script><template><div class="admin-page"><header class="top"><div><p>ADMINISTRATION / VENDORS</p><h1>Vendors</h1></div><button :disabled="creating" @click="createOpen=true"><Plus :size="17"/>Create vendor</button></header><div class="filters"><label><Search :size="16"/><input v-model="q" type="search" placeholder="Search name, email or code"/></label><select v-model="status"><option value="">All statuses</option><option value="active">Active</option><option value="suspended">Suspended</option></select></div><div v-if="loading" class="state">Loading vendors...</div><div v-else-if="error&&!createOpen" class="state error">{{error}}</div><div v-else-if="!items.length" class="state">No vendors found.</div><div v-else class="table"><table><thead><tr><th>Code</th><th>Business</th><th>Contact</th><th>Email</th><th>Phone</th><th>Products</th><th>Status</th><th>Created</th></tr></thead><tbody><tr v-for="v in items" :key="v.id"><td data-label="Code"><router-link :to="`/admin/vendors/${v.id}`">{{v.code}}</router-link></td><td data-label="Business">{{v.business_name}}</td><td data-label="Contact">{{v.contact_name||'-'}}</td><td data-label="Email">{{v.email}}</td><td data-label="Phone">{{v.phone||'-'}}</td><td data-label="Products">{{v.product_count??0}}</td><td data-label="Status"><StatusBadge :status="v.status"/></td><td data-label="Created">{{date(v.created_at)}}</td></tr></tbody></table></div><div v-if="createOpen" class="backdrop" @click.self="createOpen=false"><section class="dialog"><h2>Create vendor</h2><div v-if="error" class="error">{{error}}</div><form @submit.prevent="create"><label>Business name<input v-model="form.business_name" required/><small>{{fields.business_name}}</small></label><label>Contact name<input v-model="form.contact_name"/></label><label>Email<input v-model="form.email" type="email" required/><small>{{fields.email}}</small></label><label>Phone<input v-model="form.phone"/></label><div class="actions"><button type="button" @click="createOpen=false">Cancel</button><button class="save" :disabled="creating">{{creating?'Creating...':'Create vendor'}}</button></div></form></section></div></div></template><style scoped>.admin-page{padding:18px 28px}.top{display:flex;justify-content:space-between;align-items:center}.top p{margin:0;color:#075397;font-size:.66rem;font-weight:800}.top h1{margin:4px 0 16px}.top button{height:42px;padding:0 14px;border:0;border-radius:6px;background:#ff7900;color:#fff;display:flex;align-items:center;gap:7px;font-weight:800}.filters{display:flex;gap:10px;margin-bottom:14px}.filters label{height:42px;min-width:260px;display:flex;align-items:center;gap:7px;padding:0 10px;border:1px solid #dbe3ec;border-radius:6px;background:#fff}.filters input{width:100%;border:0;outline:0}.filters select{height:42px;padding:0 10px;border:1px solid #dbe3ec;border-radius:6px}.table{border:1px solid #e6ebf1;border-radius:8px;background:#fff;overflow:hidden}table{width:100%;border-collapse:collapse}th,td{padding:11px;border-bottom:1px solid #edf0f3;text-align:left}th{color:#64748b;font-size:.72rem}.table a{color:#075397;font-weight:800}.state{padding:30px;text-align:center;border:1px solid #e6ebf1;border-radius:8px;background:#fff}.error{color:#b42318}.backdrop{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:18px;background:rgba(15,42,68,.42)}.dialog{width:min(480px,100%);padding:22px;border-radius:8px;background:#fff}.dialog h2{margin:0 0 14px}.dialog form{display:flex;flex-direction:column;gap:10px}.dialog label{display:flex;flex-direction:column;gap:5px;font-size:.78rem;font-weight:750}.dialog input{height:42px;padding:0 10px;border:1px solid #cbd5e1;border-radius:6px}.dialog small{color:#b42318}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:8px}.actions button{height:40px;padding:0 12px;border:1px solid #dbe3ec;border-radius:6px;background:#fff;font-weight:750}.actions .save{border:0;background:#ff7900;color:#fff}@media(max-width:760px){.admin-page{padding:14px}.filters{flex-direction:column}.filters label{min-width:0}.table{border:0;background:transparent}table,tbody,tr,td{display:block}thead{display:none}tr{margin-bottom:10px;padding:8px;border:1px solid #e6ebf1;border-radius:8px;background:#fff}td{display:flex;justify-content:space-between;border:0;padding:7px}td::before{content:attr(data-label);color:#64748b;font-weight:700}}</style>